import { CAT_LANDMARK } from 'config/baseConfig';
import * as React from 'react';
import { useTranslation } from 'react-i18next';

import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import { Box, Link } from '@mui/material';

import GamePicture from 'components/ui/GamePicture';
import NoPicture from 'components/ui/NoPicture';
import { CountryLabelWithFlag } from 'components/wiki/CountryLabelWithFlag';
import WikiCard, { CardTable, CardTitle } from 'components/wiki/WikiCard';

const LandmarkCard = (props) => {
    const { landmark, onNext, onPrevious, onClickCountry } = props;
    const { i18n, t } = useTranslation();

    if (!landmark) {
        return null;
    }

    const countries =
        landmark.country && landmark.country.length
            ? landmark.country.map((c, index) => {
                  return (
                      <CountryLabelWithFlag
                          key={c.cca3}
                          country={c}
                          onClickCountry={onClickCountry}
                          language={i18n.language}
                      />
                  );
              })
            : '';

    const cardTableRows = [
        // {
        //     label: t('Other Names'),
        //     value: landmark.name_complete,
        // },
        {
            label: t('Country'),
            value: countries,
        },
        // {
        //     label: t('Type'),
        //     value: landmark.type.map((ty) => t(ty)),
        // },
        // {
        //     label: t('Region'),
        //     value: landmark.getRegion(i18n.language),
        // },
        ...(landmark.coord
            ? [
                  {
                      label: t('Coordinates'),
                      value: (
                          <Link href={`https://www.google.ca/maps/place/${landmark.coord}`} target="_blank">
                              {landmark.coord}
                              &nbsp;
                              <OpenInNewIcon
                                  size="small"
                                  sx={{ verticalAlign: 'middle', width: '0.75em', height: '0.75em' }}
                              />
                          </Link>
                      ),
                  },
              ]
            : []),
    ];

    return (
        <WikiCard>
            <CardTitle title={landmark.getName(i18n.language)} onPrevious={onPrevious} onNext={onNext} />
            <Box
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    height: '25vh',
                }}
            >
                {landmark.images && landmark.images.length > 0 ? (
                    <GamePicture
                        image={landmark.images[0]} // Math.floor(Math.random()*landmark.images.length)
                        images={landmark.images} // Math.floor(Math.random()*landmark.images.length)
                        altText={landmark.getName()}
                        overrideSx={{
                            height: 'auto',
                            maxHeight: '25vh',
                            width: 'auto',
                        }}
                    />
                ) : (
                    <NoPicture icon={CAT_LANDMARK} />
                )}
            </Box>
            <CardTable aria={`landmark ${landmark.getName(i18n.language)}`} rows={cardTableRows} />
        </WikiCard>
    );
};

export default LandmarkCard;
